type Request struct {
    args       []int
    f          func([]int) int
    resultChan chan int          // the ACT the client owns
}
func handle(queue chan *Request) {
    for req := range queue {
        req.resultChan <- req.f(req.args)    // completion delivered to the token
    }
}
